:root {
  color-scheme: dark;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #000;
  font-family: "Courier New", monospace;
}

/* O canvas ocupa a tela inteira. O tamanho real do framebuffer
   é ajustado por JS considerando o devicePixelRatio. */
#gpu-canvas {
  display: block;
  width: 100vw;
  height: 100vh;
}

