// ============================================================
//  Renderer — Desenha a cena usando WebGPU
// ------------------------------------------------------------
//  FASE 1: cria o pipeline de render, um vertex buffer com um
//  triângulo colorido e executa uma render pass por frame.
//
//  Divisão CPU x GPU nesta fase:
//    CPU (este arquivo):
//      - monta os dados dos vértices (Float32Array);
//      - cria GPUBuffer e envia os dados p/ a GPU;
//      - descreve o pipeline (shaders, layout, formato);
//      - a cada frame grava comandos e os submete à fila da GPU.
//    GPU (shaders WGSL):
//      - transforma vértices (vertex shader);
//      - colore os pixels (fragment shader).
// ============================================================

import { GPUContext } from "../gpu/GPUContext";
import vertexShaderSrc from "../shaders/triangle.vert.wgsl?raw";
import fragmentShaderSrc from "../shaders/triangle.frag.wgsl?raw";

// Layout de cada vértice: 2 floats de posição + 3 floats de cor = 5 floats.
const FLOATS_PER_VERTEX = 5;
const VERTEX_STRIDE_BYTES = FLOATS_PER_VERTEX * Float32Array.BYTES_PER_ELEMENT; // 20 bytes

export class Renderer {
  private readonly gpu: GPUContext;
  private readonly pipeline: GPURenderPipeline;
  private readonly vertexBuffer: GPUBuffer;
  private readonly vertexCount: number;

  constructor(gpu: GPUContext) {
    this.gpu = gpu;
    const { device, format } = gpu;

    // ---------------------------------------------------------
    // 1) Dados dos vértices (na CPU).
    //    Um triângulo em clip space (-1..1). Cada linha:
    //       x,    y,     r,   g,   b
    // ---------------------------------------------------------
    // prettier-ignore
    const vertices = new Float32Array([
       0.0,  0.6,    1.0, 0.2, 0.2,  // topo    — vermelho
      -0.6, -0.6,    0.2, 1.0, 0.2,  // esq.    — verde
       0.6, -0.6,    0.2, 0.4, 1.0,  // dir.    — azul
    ]);
    this.vertexCount = vertices.length / FLOATS_PER_VERTEX;

    // ---------------------------------------------------------
    // 2) Cria o GPUBuffer e copia os dados da CPU para a GPU.
    //    usage VERTEX: será lido como vertex buffer.
    //    usage COPY_DST: podemos escrever nele com writeBuffer.
    // ---------------------------------------------------------
    this.vertexBuffer = device.createBuffer({
      label: "triangle-vertices",
      size: vertices.byteLength,
      usage: GPUBufferUsage.VERTEX | GPUBufferUsage.COPY_DST,
    });
    device.queue.writeBuffer(this.vertexBuffer, 0, vertices);

    // ---------------------------------------------------------
    // 3) Compila os shaders WGSL em GPUShaderModules.
    // ---------------------------------------------------------
    const vertexModule = device.createShaderModule({
      label: "triangle.vert",
      code: vertexShaderSrc,
    });
    const fragmentModule = device.createShaderModule({
      label: "triangle.frag",
      code: fragmentShaderSrc,
    });

    // ---------------------------------------------------------
    // 4) Descreve como a GPU lê cada vértice do buffer.
    //    Precisa casar com os @location() do vertex shader.
    // ---------------------------------------------------------
    const vertexBufferLayout: GPUVertexBufferLayout = {
      arrayStride: VERTEX_STRIDE_BYTES,
      attributes: [
        // @location(0) position: vec2<f32> — offset 0
        { shaderLocation: 0, offset: 0, format: "float32x2" },
        // @location(1) color: vec3<f32> — offset 8 bytes (após os 2 floats)
        { shaderLocation: 1, offset: 2 * 4, format: "float32x3" },
      ],
    };

    // ---------------------------------------------------------
    // 5) Cria o render pipeline: junta shaders, layout de vértice
    //    e o formato de saída (o mesmo do canvas).
    // ---------------------------------------------------------
    this.pipeline = device.createRenderPipeline({
      label: "triangle-pipeline",
      layout: "auto",
      vertex: {
        module: vertexModule,
        entryPoint: "main",
        buffers: [vertexBufferLayout],
      },
      fragment: {
        module: fragmentModule,
        entryPoint: "main",
        targets: [{ format }],
      },
      primitive: {
        topology: "triangle-list",
      },
    });
  }

  // Desenha um frame. Chamado pelo game loop.
  render(): void {
    const { device, context } = this.gpu;

    // 1) Encoder: acumula os comandos que serão enviados à GPU.
    const encoder: GPUCommandEncoder = device.createCommandEncoder({
      label: "frame-encoder",
    });

    // 2) Textura atual do canvas — onde a GPU vai desenhar este frame.
    const view: GPUTextureView = context.getCurrentTexture().createView();

    // 3) Abre a render pass. loadOp "clear" limpa a tela com a cor de fundo.
    const pass: GPURenderPassEncoder = encoder.beginRenderPass({
      label: "triangle-pass",
      colorAttachments: [
        {
          view,
          clearValue: { r: 0.04, g: 0.04, b: 0.06, a: 1.0 }, // fundo escuro
          loadOp: "clear",
          storeOp: "store",
        },
      ],
    });

    // 4) Grava os comandos de desenho.
    pass.setPipeline(this.pipeline);
    pass.setVertexBuffer(0, this.vertexBuffer);
    pass.draw(this.vertexCount); // 3 vértices → 1 triângulo
    pass.end();

    // 5) Finaliza o encoder e submete os comandos para a fila da GPU.
    device.queue.submit([encoder.finish()]);
  }
}

src/shaders/triangle.frag.wgsl:
// ============================================================
//  FRAGMENT SHADER — triangle.frag.wgsl
// ------------------------------------------------------------
//  Executado NA GPU, uma vez por fragmento (≈ pixel coberto
//  pelo triângulo).
//
//  ENTRA (vindo interpolado do vertex shader):
//    - color: cor RGB interpolada entre os vértices.
//
//  SAI:
//    - @location(0): cor final RGBA escrita no framebuffer
//      (a textura da tela configurada no canvas).
//
//  A interpolação suave entre as cores dos três vértices é feita
//  automaticamente pela GPU (rasterizador) — nós só recebemos o
//  valor já interpolado aqui.
// ============================================================

// Deve casar com o VertexOutput do vertex shader (mesmos @location).
struct FragmentInput {
  @location(0) color : vec3<f32>,
};

@fragment
fn main(in : FragmentInput) -> @location(0) vec4<f32> {
  // Alpha = 1.0 (totalmente opaco).
  return vec4<f32>(in.color, 1.0);
}

src/shaders/triangle.vert.wgsl:
// ============================================================
//  VERTEX SHADER — triangle.vert.wgsl
// ------------------------------------------------------------
//  Executado NA GPU, uma vez por vértice.
//
//  ENTRA (vindo do vertex buffer, preenchido pela CPU):
//    - position: posição 2D do vértice no espaço de clip.
//    - color:    cor RGB do vértice.
//
//  SAI (interpolado pela GPU antes de chegar ao fragment shader):
//    - @builtin(position): posição final em clip space (obrigatória).
//    - color:              cor repassada ao fragment shader.
//
//  Nesta FASE 1 ainda NÃO há matrizes Model/View/Projection.
//  As posições já estão em clip space (intervalo -1..1), então o
//  vertex shader apenas as repassa. As matrizes chegam na FASE 2.
// ============================================================

// Dados de um vértice, exatamente no layout do vertex buffer.
struct VertexInput {
  @location(0) position : vec2<f32>,  // x, y em clip space
  @location(1) color    : vec3<f32>,  // r, g, b
};

// Dados que saem do vertex shader e entram no fragment shader.
struct VertexOutput {
  @builtin(position) clip_position : vec4<f32>,  // posição obrigatória
  @location(0)       color         : vec3<f32>,  // cor interpolada
};

@vertex
fn main(in : VertexInput) -> VertexOutput {
  var out : VertexOutput;

  // Converte a posição 2D em vec4 (z = 0, w = 1).
  out.clip_position = vec4<f32>(in.position, 0.0, 1.0);

  // Repassa a cor; a GPU a interpola entre os três vértices.
  out.color = in.color;

  return out;
}
